def compute(vars):
    debt_to_equity_ratio = vars["Debt to Equity Ratio"]
    total_liabilities = vars["Total Liabilities"]

    if debt_to_equity_ratio == 0:
        return None

    total_shareholders_equity = total_liabilities / debt_to_equity_ratio
    return {
        "value": total_shareholders_equity,
        "trace": {
            "Debt to Equity Ratio": debt_to_equity_ratio,
            "Total Liabilities": total_liabilities,
            "output_meta": {
                "currency": "$",
                "scale": "billion",
                "unit": None
            }
        }
    }
